"""Historical statistics quoted to users, generated by research/analyze.py (see research/REPORT.md)."""

import json
from pathlib import Path
from typing import Optional

_STATS = json.loads((Path(__file__).with_name("stats.json")).read_text(encoding="utf-8"))

PERIOD: str = _STATS["generated_from"]


def reaction(title: str) -> Optional[dict]:
    """How often gold moved against the USD surprise after this release: {n, against_1m, against_15m, median_move_15m}."""
    return _STATS["reaction"].get(title)


def straddle(title: str) -> Optional[dict]:
    """Backtest of the straddle plan on this release: {trades, win, exp_r, total_r}."""
    return _STATS["straddle"].get(title)


def is_plannable(title: str) -> bool:
    """Only releases where the straddle had a positive expectancy in the backtest get a trade plan."""
    stats = straddle(title)
    return bool(stats and stats["exp_r"] > 0)
